import { createHeaderResolver, createJwtResolver, createResolverChain } from "@zudojs/tenancy";

const fakeRequest = (r) => ({
  getClaims: () => r.claims,
  getHost: () => r.host,
  getHeader: (name) => r.headers?.[name],
  getPath: () => "/tasks",
});
const chain = createResolverChain([createJwtResolver(), createHeaderResolver()]);

for (const request of [
  { claims: { tenant_id: "acme" } },
  { headers: { "x-tenant-id": "globex" } },
]) {
  const found = await chain.resolveTenant(fakeRequest(request));
  console.log(found.tenantId, found.source, found.trust);
}

