function cleanTenantId(raw) {
  const id = raw.trim().toLowerCase();
  return /^[a-z0-9][a-z0-9_-]*$/.test(id) ? id : undefined;
}

console.log(cleanTenantId("  ACME "), cleanTenantId("acme:admin"), cleanTenantId("../globex"), cleanTenantId("Acme-EU"));

