const rows = [
  { id: 1, tenantId: "acme", title: "Acme task" },
  { id: 2, tenantId: "globex", title: "Globex task" },
];

function rename(tenantId, id, title) {
  const row = rows.find((r) => r.id === id && r.tenantId === tenantId);
  if (!row) return false;
  row.title = title;
  return true;
}

